SELECT package_name, published_at AS burst_start, version, release_lines, releases FROM (SELECT package_name, version, published_at, ts, size(collect_set(release_line) OVER (PARTITION BY package_name ORDER BY ts RANGE BETWEEN CURRENT ROW AND 600 FOLLOWING)) AS release_lines, count(*) OVER (PARTITION BY package_name ORDER BY ts RANGE BETWEEN CURRENT ROW AND 600 FOLLOWING) AS releases, ts - lag(ts) OVER (PARTITION BY package_name ORDER BY ts) AS secs_since_prev FROM (SELECT package_name, version, published_at, unix_timestamp(published_at) AS ts, concat(split(version, '\\.')[0], '.', split(split(version, '-')[0], '\\.')[1]) AS release_line FROM pkgtrail.releases_table) x) y WHERE release_lines >= 3 AND (secs_since_prev IS NULL OR secs_since_prev > 600) ORDER BY package_name, published_at
